/* /* */
#include <iostream>
#include <string>
#include <algorithm>

std::string add(const std::string& x, const std::string& y) {
    std::string result;
    int i = static_cast<int>(x.size()) - 1;
    int j = static_cast<int>(y.size()) - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry > 0) {
        int sum = carry;
        if (i >= 0) sum += x[i--] - '0';
        if (j >= 0) sum += y[j--] - '0';
        result.push_back(static_cast<char>('0' + sum % 10));
        carry = sum / 10;
    }
    std::reverse(result.begin(), result.end());
    return result;
}

int main(int argc, char** argv) {
    unsigned long long n = std::stoull(argv[1]);
    std::string a = "1";
    std::string b = "1";
    for (unsigned long long i = 0; i < n; ++i) {
        std::string t = add(a, b);
        a = b;
        b = t;
    }
    std::cout << a << '\n';
    return 0;
}
